mkdir -p "$(dirname calc_bytes.py)" && printf %s 'import csv
import os

def calculate_success_bytes(filename):
    total_bytes = 0
    try:
        with open(filename, mode='"'"'r'"'"') as f:
            reader = csv.DictReader(f)
            for row in reader:
                if row['"'"'status'"'"'].strip() == '"'"'success'"'"':
                    total_bytes += int(row['"'"'value'"'"'])
        return total_bytes
    except Exception as e:
        print(f"Error: {e}")
        return None

if __name__ == "__main__":
    result = calculate_success_bytes('"'"'requests.csv'"'"')
    if result is not None:
        os.makedirs('"'"'out'"'"', exist_ok=True)
        with open('"'"'out/result.txt'"'"', '"'"'w'"'"') as f:
            f.write(str(result))
        print(f"Total success bytes: {result}")
    else:
        print("Failed to calculate bytes.")
